INSERT INTO decisions (id, title, category, context, options_considered, data_consulted,
  decision_made, rationale, expected_outcome, review_date, status, actual_outcome, team, owner, decided_at)
VALUES
(41,
 'Relocate primary fulfillment center from New Jersey to Ohio',
 'operational',
 'Current NJ fulfillment center (3PL: Shipbob NJ) serves 62% of subscribers with average delivery 5.2 days. Analysis shows moving to Ohio (Shipbob Columbus) would put 71% of subscribers within 2-day ground and reduce per-unit shipping cost from $8.40 to $6.10 due to better UPS zone alignment. Lease at NJ facility renews in April.',
 '[{"option":"Renew NJ — no move","pros":["operational continuity"],"cons":["miss $2.30/unit saving ($345K ARR)","5.2-day average persists"]},{"option":"Move to Columbus Ohio via Shipbob","pros":["$2.30/unit saving","3.1-day avg delivery","71% of subscribers in 2-day zone"],"cons":["6-week transition risk","temporary dual-fulfillment cost during cutover"]},{"option":"Second facility (NJ + OH dual)","pros":["optimal coverage","no disruption"],"cons":["dual 3PL cost is prohibitive at current scale"]}]'::jsonb,
 ARRAY['Shipbob Columbus pricing proposal','UPS zone analysis: subscriber zip code distribution','Delivery time comparison: NJ vs OH for top 20 subscriber markets','Fulfillment cost model 2026'],
 'Transition to Shipbob Columbus. Run parallel fulfillment NJ + OH for 3 weeks during transition. Complete full cutover by March 1.',
 'The Ohio move saves $2.30 per unit — $345K annually at current volume — while improving delivery time for 71% of subscribers. The NJ lease renewal in April is the forcing function. The 3-week parallel run eliminates transition risk.',
 'Shipping cost per unit ≤$6.20; average delivery time ≤3.5 days; zero subscriber-facing disruption during transition.',
 '2026-04-14',
 'succeeded',
 'Shipping cost per unit: $6.10 (at target). Average delivery time: 3.1 days (vs 5.2 days — 40% improvement). Zero subscriber complaints attributed to the transition. Dual-fulfillment period ran cleanly; Columbus fully operational March 1 on schedule. Annualized saving vs NJ: $364K.',
 'Operations',
 'Aiko Yamamoto',
 '2026-01-14 09:00:00+00'),

(42,
 'Migrate API services from bare-metal EC2 to Kubernetes (EKS)',
 'operational',
 'API services run on 6 fixed EC2 instances with manual scaling. During the November 2025 Black Friday flash sale, API latency spiked to 4.2s causing checkout abandonment. Kubernetes enables autoscaling to handle traffic spikes, reduces deploy time from 45 minutes to under 10, and cuts infrastructure cost via bin-packing.',
 '[{"option":"Stay on EC2 — add more fixed instances","pros":["familiar","low operational complexity"],"cons":["does not solve spike problem","cost scales linearly with peak provisioning","45-minute deploys remain"]},{"option":"Migrate to EKS (Kubernetes on AWS)","pros":["autoscaling handles spikes","deploy time 8 minutes","estimated 22% cost reduction via bin-packing"],"cons":["migration risk","3-4 week engineering effort","team needs k8s training"]},{"option":"AWS Lambda (serverless)","pros":["infinite scale","pay per use"],"cons":["not appropriate for stateful services","cold starts cause latency on our low-traffic services"]}]'::jsonb,
 ARRAY['Black Friday 2025 incident postmortem','EC2 infrastructure cost analysis ($18K/month)','EKS migration estimate (Engineering team)','AWS EKS pricing model','Kubernetes adoption benchmarks: companies at similar scale'],
 'Migrate all 6 API services to EKS. 4-week migration plan with staging environment first, then production services one-by-one. Target full EKS operation by March 15.',
 'The Black Friday incident demonstrated that fixed EC2 instances cannot handle traffic spikes safely. EKS autoscaling directly solves this. The 45-minute deploy time is also a product velocity bottleneck — 8-minute deploys will increase our deployment frequency.',
 'API p99 latency ≤800ms during 3× normal traffic; deploy time ≤10 minutes; infrastructure cost reduction ≥18%.',
 '2026-04-28',
 'succeeded',
 'EKS fully operational March 14. API p99 at 3× normal traffic: 520ms (well below 800ms threshold). Deploy time: 7 minutes average. Infrastructure cost fell from $18K to $13.8K/month (23% reduction — above 18% target). Stress test at 5× normal traffic: no latency breach. Two additional services migrated ahead of schedule.',
 'Engineering',
 'Paulo Rivera',
 '2026-01-28 11:00:00+00'),

(43,
 'Migrate cloud infrastructure from GCP to AWS',
 'operational',
 'Nexura has used GCP since founding. Engineering team has stronger AWS expertise (3 of 4 backend engineers are AWS-certified). EKS migration (decision 42) is AWS-native. S3+CloudFront outperforms GCS+Cloud CDN for our media asset workload. AWS monthly bill would be $61K vs GCP $84K based on workload mapping.',
 '[{"option":"Stay on GCP","pros":["no migration effort","existing stack knowledge"],"cons":["$23K/month higher than AWS equivalent","GCP CDN performance gap on our media workload","team AWS expertise underutilized"]},{"option":"Full AWS migration","pros":["$23K/month saving ($276K/year)","CDN performance improvement","team expertise match"],"cons":["3-month migration effort","dual-cloud cost during cutover (~$12K)"]},{"option":"Hybrid: GCP data + AWS compute","pros":["phased risk"],"cons":["hybrid complexity costs more to operate than either single-cloud"]}]'::jsonb,
 ARRAY['GCP vs AWS workload cost comparison (CloudHealth)','Engineering team cloud certification audit','CDN performance benchmark: CloudFront vs GCS CDN','Migration feasibility estimate (Engineering)','GCP contract termination terms'],
 'Full migration from GCP to AWS. 8-week migration plan. Priority: data stores first (BigQuery → Redshift, GCS → S3), then compute. Target completion May 10.',
 'AWS is the right long-term choice given team expertise, EKS migration in progress, and $276K annual saving. The data migration is the highest-risk component; we will run parallel replication for 2 weeks before cutting over data stores.',
 'AWS monthly bill ≤$62K; CDN p95 latency improvement ≥20%; zero data loss during migration; GCP contract terminated by June 1.',
 '2026-05-10',
 'succeeded',
 'AWS migration completed May 8 (2 days ahead of schedule). AWS monthly bill: $59K (below $62K target). CDN p95 improvement: 34% (above 20% target). Zero data loss confirmed by MD5 checksum audit post-migration. GCP contract terminated May 15 with €6K early termination fee (within budget). Engineers report 40% faster deployment cycle on AWS tooling.',
 'Engineering',
 'Paulo Rivera',
 '2026-02-10 14:00:00+00'),

(44,
 'Replace legacy payment processor with Stripe as primary processor',
 'operational',
 'Current payment processor (Braintree) has a 3.2% payment failure rate — 3× the industry benchmark of 1.0%. International card failures are 7.1% (for UK/Canada expansion this is critical). Stripe''s smart retry and network tokenization features have been shown to reduce failure rates to <1.1% in comparable businesses.',
 '[{"option":"Stay on Braintree","pros":["no switching cost"],"cons":["3.2% failure rate is $390K/year in lost revenue at current scale","7.1% international failure will kill EU expansion economics"]},{"option":"Switch to Stripe as primary","pros":["smart retry reduces failure rate","network tokenization","Stripe Billing has superior subscription management","EU payment method support (SEPA, iDEAL, Bancontact)"],"cons":["4-week integration","0.1% higher per-transaction fee than Braintree"]},{"option":"Add Stripe as secondary (failover)","pros":["lower migration risk"],"cons":["dual-processor complexity","does not get us the full Stripe Billing subscription management benefits"]}]'::jsonb,
 ARRAY['Braintree payment failure rate analysis 2025','Stripe ROI calculator: recovery rate improvement estimate','EU payment methods required for France/Spain/Netherlands','Stripe integration timeline estimate (Engineering)','PCI DSS compliance comparison'],
 'Replace Braintree with Stripe as sole payment processor. 4-week migration with Braintree maintained as fallback for first 2 weeks. Complete cutover by April 25.',
 'Payment failure is a direct revenue leak and a churn trigger (failed payment → involuntary churn accounts for 18% of Nexura churns). Stripe''s recovery features (smart retry, updater) directly address this. EU payment method support is a prerequisite for France/Spain/Netherlands launches.',
 'Payment failure rate ≤1.2%; international card failure rate ≤2.0%; involuntary churn from payment failure decrease ≥30%.',
 '2026-04-25',
 'succeeded',
 'Payment failure rate: 1.1% (vs 3.2% baseline — 66% reduction). International failure rate: 1.8% (vs 7.1% — 75% reduction). Involuntary churn from payment failure fell 41%. Stripe Billing''s dunning automation recovered $28K in previously-failed subscriptions in the first 30 days. PCI compliance audit passed with no findings. EU payment methods (SEPA Direct Debit, iDEAL) live and tested.',
 'Engineering',
 'Paulo Rivera',
 '2026-02-25 09:00:00+00'),

(45,
 'Automate box curation workflow with ML demand forecasting integration',
 'operational',
 'Box curation (selecting which products go in each subscriber''s monthly box based on their quiz profile and history) requires 40 person-hours per week from the category buying team. The process is manual, spreadsheet-based, and error-prone — 12% of boxes in Q4 2025 contained a product the subscriber had already received in the prior 3 months. With the data science team (decision 23) and ML models available, automation is now feasible.',
 '[{"option":"Keep manual curation","pros":["human judgment","editorial quality"],"cons":["40 hrs/week cost","12% repeat-product rate","does not scale with subscriber growth"]},{"option":"ML-automated curation with human QA review","pros":["scales without headcount","reduces repeat products","incorporates personalization signals"],"cons":["4-week build","initial model accuracy needs validation period"]},{"option":"Rule-based automation (no ML)","pros":["faster to build — 1 week"],"cons":["cannot handle personalization complexity","does not improve with data"]}]'::jsonb,
 ARRAY['Category buying team time audit 2025','Repeat-product rate analysis Q4 2025','ML curation feasibility study (Priya Menon)','Subscriber complaint analysis: product repeats','Demand forecasting model specification'],
 'Build ML-automated curation pipeline. Category buyer team shifts to QA/exception review (approving, not generating, curation lists). Target: automated curation for ≥90% of subscriber boxes by April 15.',
 'Curation automation directly addresses both the 12% repeat-product rate and the 40 hr/week manual cost. The ML model is trained on subscriber history, quiz answers, and product ratings from the new rating system. Human QA review for the first 60 days ensures quality before reducing oversight.',
 'Curation time ≤8 person-hours/week; repeat-product rate ≤3%; subscriber post-ship satisfaction rating ≥4.2/5.',
 '2026-06-04',
 'succeeded',
 'Curation now requires 5 person-hours/week (vs 40 — 87.5% reduction). Repeat-product rate: 1.4% (vs 12% — 88% improvement). Post-ship satisfaction: 4.4/5. Category buyers now focus on supplier sourcing and product quality evaluation. Automation handles 94% of boxes; the 6% exception rate is routed to human review (edge cases like hypoallergenic requirements).',
 'Operations',
 'Aiko Yamamoto',
 '2026-03-04 09:00:00+00'),

(46,
 'Pilot 100% zero-waste biodegradable packaging with premium supplier',
 'operational',
 'Packaging sustainability is a stated priority (see decision 15, which addressed outer box). This decision addresses the inner protective materials: void fill, tissue paper, and product wrappers. Premium biodegradable alternatives from Novamont are quoted at €0.42/unit vs €0.29/unit current. The 45% cost increase would be offset by the ESG marketing value and potential price premium.',
 '[{"option":"Keep current inner packaging","pros":["lowest cost","proven durability"],"cons":["plastic void fill contradicts sustainability brand positioning"]},{"option":"Switch to Novamont biodegradable inner packaging","pros":["full sustainability story","ESG marketing value","subscriber demand signal from survey (81% care)"],"cons":["45% cost increase: +€0.13/box","structural integrity unproven at scale for our product format"]},{"option":"Partial switch: biodegradable tissue only (cheapest change)","pros":["partial sustainability gain","lower cost"],"cons":["incomplete story — void fill still plastic"]}]'::jsonb,
 ARRAY['Novamont product proposal and pricing','Inner packaging sustainability survey (81% subscribers care)','COGS impact model: +€0.13/box x 150K boxes = +€19.5K/month','Structural integrity stress test: Novamont materials'],
 'Pilot Novamont biodegradable inner packaging for 30% of boxes in April. Evaluate damage rate, COGS, and subscriber NPS impact after 60 days before full rollout decision.',
 'The pilot limits financial exposure while validating the structural integrity concern. If damage rate is comparable to current (<2.5%) and subscriber NPS improves, full rollout is justified by the ESG marketing value. The 45% material cost increase is manageable if subscriber NPS lifts materially.',
 'Pilot damage rate ≤2.5% (comparable to current 2.1%); NPS lift ≥3 points from sustainability messaging; COGS increase ≤€0.15/box.',
 '2026-06-20',
 'reversed',
 'Pilot damage rate: 7.8% — 3.7× the 2.5% threshold and 3.7× current baseline. Novamont inner packaging was insufficiently rigid for glass product items in our Wellness boxes. COGS was €0.41/box increase (vs €0.13 projection — supplier had miscalculated unit pricing). NPS in pilot group: flat (no improvement from sustainability messaging vs control). Pilot reversed June 2. Pursuing alternative biodegradable supplier with proven glass-product compatibility.',
 'Operations',
 'Aiko Yamamoto',
 '2026-03-20 11:00:00+00'),

(47,
 'Implement Snowflake as centralized data warehouse',
 'operational',
 'Data is currently siloed across PostgreSQL (transactional), Google Sheets (manual reports), Stripe exports (revenue), Shipbob exports (logistics). The data science team cannot run cross-domain analyses without manual data extraction. A proper data warehouse enables self-serve analytics, the ML pipeline, and accurate cross-functional reporting.',
 '[{"option":"Continue with ad-hoc data pulls","pros":["no cost"],"cons":["6+ hours/week data engineering time wasted on manual extractions","ML team bottlenecked waiting for clean data"]},{"option":"Snowflake + dbt for transformation layer","pros":["industry standard at our scale","native Fivetran connectors for Stripe and Shipbob","dbt enables version-controlled transformations"],"cons":["$2,800/month estimated cost","4-week setup"]},{"option":"BigQuery (already in GCP)","pros":["already have GCP account"],"cons":["switching to AWS (decision 43) — BigQuery becomes a cross-cloud dependency"]}]'::jsonb,
 ARRAY['Data engineering time audit 2025','Snowflake vs BigQuery vs Redshift evaluation (Data Science team)','Fivetran connector availability for our data sources','dbt capability review','Analytics team self-serve reporting requirements'],
 'Implement Snowflake with Fivetran EL and dbt transformation layer. Connect Stripe, Shipbob, PostgreSQL, and Nexura app events. Build 12 core business dashboards. Target: operational by September 6.',
 'Snowflake is the right choice given our AWS migration (decision 43) and the availability of Fivetran connectors for all our data sources. dbt enables the transformation layer to be version-controlled and testable — critical for ML feature pipelines.',
 'Cross-domain data available in Snowflake within 24 hours of source event; ad-hoc data extraction time ≤1 hour/week; ML team pipeline latency ≤6 hours; 12 core dashboards operational at launch.',
 '2026-09-06',
 'active',
 NULL,
 'Engineering',
 'Priya Menon',
 '2026-04-14 14:00:00+00'),

(48,
 'Implement Segment as Customer Data Platform',
 'operational',
 'Customer data is fragmented: website behavior in GA4, mobile events in Mixpanel, email engagement in Klaviyo, and purchase data in PostgreSQL. No single source of truth for a customer''s cross-channel journey. A CDP (Segment) creates a unified customer profile and enables personalized communications across all channels from a single event stream.',
 '[{"option":"Keep fragmented tools — better attribution only","pros":["no implementation cost"],"cons":["personalization is impossible across channels","ML team lacks unified event stream","marketing runs duplicate campaigns due to data gaps"]},{"option":"Segment as CDP — unify all data sources","pros":["single customer identity","real-time event stream for ML","enables cross-channel personalization"],"cons":["$3,200/month","8-week implementation","requires eng time to instrument events"]},{"option":"Build internal event bus","pros":["full control","lower cost"],"cons":["12-week build","ongoing maintenance — not core competency"]}]'::jsonb,
 ARRAY['Current martech stack audit','Segment pricing for our event volume','ML team data requirements for personalization','Marketing campaign deduplication audit (estimated 22% over-spend due to identity fragmentation)','CDP evaluation: Segment vs Rudderstack vs mParticle'],
 'Implement Segment as CDP. Connect website, iOS app, Android app (when live), email (Klaviyo), and PostgreSQL as sources. Build unified customer profile. Target: operational by September 6.',
 'Identity fragmentation is costing us in two ways: estimated 22% marketing over-spend due to duplicate targeting, and inability to run the personalized cross-channel experiences that drive retention. Segment solves both and feeds the ML feature pipeline with a unified event stream.',
 'Customer identity match rate ≥90% across channels; marketing campaign deduplication saving ≥15% of budget; ML pipeline receives unified events within 15 minutes of source event.',
 '2026-09-06',
 'active',
 NULL,
 'Engineering',
 'Aiko Yamamoto',
 '2026-05-06 10:00:00+00'),

(49,
 'Replace legacy ERP with NetSuite as we scale to multi-country operations',
 'operational',
 'Current ERP (QuickBooks Online) was sufficient at US-only scale but cannot handle: multi-currency books (6 EU currencies planned), EU VAT reporting, intercompany transactions, or the inventory complexity of multi-3PL operations. NetSuite is the standard ERP for companies at our scale and growth profile.',
 '[{"option":"Extend QuickBooks with add-ons","pros":["low cost","no migration"],"cons":["QuickBooks multi-currency is limited","EU VAT is not supported","will need to migrate anyway at Series B"]},{"option":"Migrate to NetSuite","pros":["full multi-currency","EU VAT compliance built-in","CFO candidates expect NetSuite at our stage","integrates with Stripe and Shipbob natively"],"cons":["$48K implementation cost","12-16 week migration","disruption during financial close periods"]},{"option":"Xero as intermediate step","pros":["lower cost than NetSuite","good multi-currency"],"cons":["will need another migration when we outgrow Xero — do it once, do it right"]}]'::jsonb,
 ARRAY['QuickBooks limitations audit (Finance team)','NetSuite implementation proposal (Deloitte partner)','EU VAT compliance requirements assessment','CFO incoming requirements survey','NetSuite vs Xero at our scale: CPA firm recommendation'],
 'Implement NetSuite. Deloitte partner implementation. Target go-live October 28. QuickBooks maintained for US entity parallel run through Q4 close.',
 'With 6 EU markets in flight and a CFO hire in progress, we cannot operate on QuickBooks at this scale. NetSuite is the implementation we would need to do before Series B regardless — doing it now is better than during a fundraising process. The parallel run through Q4 close eliminates financial reporting risk.',
 'NetSuite live for all entities by Oct 28; EU VAT reporting automated across all active jurisdictions; QuickBooks decommissioned by Dec 31; zero financial reporting errors during cutover.',
 '2026-10-28',
 'active',
 NULL,
 'Finance',
 'Nadia Osei',
 '2026-05-28 11:00:00+00'),

(50,
 'Implement real-time inventory tracking across all 3PL partners',
 'operational',
 'Inventory data from Shipbob (US), Clipper Logistics (UK), and Relais Colis (France) arrives via daily CSV export. This 24-hour lag causes stockouts that are not detected until the daily report, resulting in partial box fulfillment for 8% of subscribers in Q4 2025. Real-time inventory APIs would reduce stockouts and enable dynamic box substitution.',
 '[{"option":"Continue daily CSV exports","pros":["no engineering work"],"cons":["8% partial fulfillment rate is a top-3 CSAT complaint","cannot react to stockouts intraday"]},{"option":"Real-time inventory via 3PL webhook APIs","pros":["intraday stockout detection","enables dynamic substitution","feeds demand forecasting model with real-time signal"],"cons":["Relais Colis API is in French documentation only — integration complexity","3-week engineering effort per 3PL"]},{"option":"Safety stock buffer (hold 15% excess inventory)","pros":["no engineering work","immediate stockout reduction"],"cons":["15% excess inventory cost is $28K/month — expensive band-aid that does not solve root cause"]}]'::jsonb,
 ARRAY['Partial fulfillment rate analysis Q4 2025 (8.1%)','3PL API capability audit: Shipbob, Clipper, Relais Colis','CSAT analysis: partial fulfillment impact on subscriber score','Inventory carrying cost model (15% safety stock scenario)','Engineering effort estimate: 3PL webhook integration'],
 'Implement real-time inventory webhooks for all 3 3PL partners. Shipbob first (best API docs), then Clipper, then Relais Colis (with French API documentation support). Target: all 3 live by November 16.',
 'Real-time inventory is foundational to operating a multi-3PL global subscription business. The 8% partial fulfillment rate is a direct CSAT driver and a source of subscriber refund cost. Safety stock is an expensive alternative that does not solve the root cause. The engineering investment is one-time; the operational benefit is permanent.',
 'Partial fulfillment rate ≤1.5% within 60 days of full implementation; intraday stockout detection time ≤15 minutes; dynamic substitution used in ≥80% of stockout scenarios.',
 '2026-11-16',
 'active',
 NULL,
 'Operations',
 'Aiko Yamamoto',
 '2026-06-16 09:00:00+00');

-- Reset sequence to avoid conflicts with future inserts
SELECT setval('decisions_id_seq', 50);


-- ─────────────────────────────────────────────────────────────────────────────
-- REVIEWS (for all 27 past-due decisions)
-- ─────────────────────────────────────────────────────────────────────────────

INSERT INTO reviews (decision_id, reviewer, actual_outcome, outcome_rating, lessons_learned, reviewed_at)
VALUES
(1, 'Nadia Osei', 'ARR lift $2.4M, churn 2.1%. Price-lock offer absorbed the highest-risk cohort. NPS held at 66 — within acceptable range.', 5, 'Give existing subscribers 60-day advance notice with a tangible retention offer (price-lock, not just notification). Churn models based on tenure cohorts were accurate.', '2026-06-06 10:00:00+00'),

(2, 'Nadia Osei', 'Annual plan attach 28% (target 20%). $1.24M upfront cash. Early retention tracking at 94%.', 5, 'The 20% discount threshold from Recurly benchmark data was exactly right. Promote to 6+ month tenure subscribers only — shorter-tenure subscribers did not convert.', '2026-04-14 14:00:00+00'),

(3, 'Nadia Osei', 'Tier failed: 18% cannibalization of core subscribers vs 6% projected. ARR declined $210K. Discontinued April 1.', 1, 'In physical subscription commerce, tiering triggers immediate downgrade among existing subscribers. This differs from SaaS where feature gating prevents full downgrade. Never launch a lower-cost tier without a 90-day rollout exclusion for existing subscribers.', '2026-05-05 09:00:00+00'),

(4, 'Marco Delgado', 'Dynamic pricing reversed after 22 hours. Customer backlash severe. Public apology blog post required. Complaint volume +280%.', 1, 'Physical subscription consumers view variable pricing as unfair in a way airline and hotel customers do not. The fairness expectation in subscription commerce is that all subscribers pay the same. Do not apply B2C pricing optimization from other industries without consumer psychology research specific to subscription commerce.', '2026-03-19 08:00:00+00'),

(5, 'Nadia Osei', 'Gift revenue +19% (target +8%). Unit volume decline 1.8% (target ≤5%). AOV on multi-month bundles up $14.20.', 5, 'Gifters are significantly more price-inelastic than self-purchasers. Occasion-driven purchases have different price sensitivity models. We can likely push gift pricing 15-20% above self-purchase pricing without material volume impact.', '2026-06-12 11:00:00+00'),

(11, 'Lena Fischer', 'App Store rating 4.7/5 from 11,400 reviews. 68% of subscribers using app as primary channel (target 50%). Push notification opt-in 38%.', 5, 'App launch is a one-shot event — the first 7 days of App Store ranking matter disproportionately. We should have coordinated the launch with a broader subscriber communication campaign. Organic App Store discovery drove 34% of downloads.', '2026-04-10 10:00:00+00'),

(12, 'Lena Fischer', 'Quiz completion 84% (target 80%). Relevance rating 4.2/5 (target 4.0). 90-day retention for v2 completers: 87%.', 5, 'Adaptive branching reduced median completion time from 4.2 to 2.8 minutes while improving relevance. The key improvement was removing the 3 generic "lifestyle" questions that had zero predictive value for product selection.', '2026-04-17 14:00:00+00'),

(13, 'Priya Menon', 'Add-on rate: 13.1% (target 12%). CTR: 26% (target 20%). Incremental revenue: $420K in 90 days.', 5, 'Collaborative filtering performed well but the cold-start fallback (quiz-based) was within 8% of the personalized model for <3-purchase subscribers — better than expected. This means the quiz is highly predictive and we should invest more in quiz data quality.', '2026-05-07 09:00:00+00'),

(14, 'Lena Fischer', 'AR engagement: 4.2% (target 22%). 72% of testers said "too inaccurate." Feature deprecated after 60 days. Total cost: $84K.', 1, 'The ModiFace case studies we relied on were for makeup try-on, not skincare. Our product mix is 60% skincare and 40% cosmetics. AR works for color cosmetics but has no utility for serums and moisturizers. Product-category match to technology is critical before licensing third-party features.', '2026-05-22 10:00:00+00'),

(15, 'Lena Fischer', 'NPS +8 points (68→76). Damage rate 2.1% (flat vs baseline). COGS: no increase. Social mentions +34%.', 5, 'The volume commitment with EcoPackaging Partners was the right mechanism — it aligned incentives and delivered cost neutrality. The NPS lift exceeded expectations. Sustainability is a genuine differentiator in beauty subscription, not just PR.', '2026-06-05 14:00:00+00'),

(16, 'Lena Fischer', 'Pause feature used by 14% of cancel-intent subscribers (target 10%). Post-pause reactivation: 71%. Net cancel rate fell 0.8pp. ARR saved: $88K in 90 days.', 5, 'The reactivation rate of 71% significantly exceeded our 60% model. Subscribers who pause are not churned — they are temporarily unavailable. The feature also surfaced "travel" and "postpartum" as the two leading pause reasons, which informs product marketing.', '2026-06-20 10:00:00+00'),

(23, 'James Okafor', 'Priya Menon hired Feb 15. Consultancy terminated same day. Recommendation engine shipped Mar 8 (21 days after onboarding). Churn model delivered Apr 2.', 5, 'The Head of Data Science hire immediately outperformed the consultancy on speed, institutional knowledge, and cost. The 6-week recruiting timeline was accurate. For future critical technical hires, brief candidates with real data problems — Priya solved a practice version of the recommendation engine problem in the final interview.', '2026-04-08 10:00:00+00'),

(24, 'James Okafor', 'All 5 agents hired by Feb 26. Response time: 3.8 hours by Mar 20 (target ≤4 hours). CSAT: 4.5/5. CS churn mentions fell 48%.', 5, 'The Emma Park Team Lead promotion was the highest-leverage action. She implemented quality feedback loops in week 1 that improved CSAT faster than we projected. Headcount alone does not drive quality — quality programs drive quality.', '2026-03-22 09:00:00+00'),

(25, 'Paulo Rivera', 'API p95: 290ms (target ≤350ms). Payment uptime 99.97%. Both engineers delivered observability (OpenTelemetry) and payment retry logic in first 4 weeks.', 5, 'Giving the engineers a specific reliability metric target (99.95% uptime) and making it their primary Q1 OKR created clear focus. Engineers with infrastructure backgrounds need outcome targets, not task lists.', '2026-04-06 14:00:00+00'),

(26, 'James Okafor', 'VP Marketing departed day 58. Total cost: $90K recruiting. EU marketing strategy not delivered. Search restarted.', 1, 'The job spec said "growth marketing experience" but did not explicitly state "product-led growth model" as a core operating context. We hired a brand-first marketer into a PLG company. The new spec has a mandatory PLG case study in round 1 screening.', '2026-05-18 10:00:00+00'),

(27, 'James Okafor', 'All 3 ML engineers started Apr 1. Churn model live May 2 (82% precision). Demand forecasting reduced stockout rate from 8.1% to 2.3%. A/B test framework for EU recommendations shipped.', 5, 'Priya Menon''s structured onboarding doc (1-week domain immersion, 2-week data exploration, 4-week model delivery) worked excellently for all 3 engineers. This onboarding template should be standardized across all technical roles.', '2026-06-08 09:00:00+00'),

(28, 'Paulo Rivera', 'QA outsource reversed Apr 20. Defect escape rate 4.1% (vs 0.8% internal). P1 payment bug reached production. Testify Pro contract terminated. Internal team retained.', 1, 'A 30-day overlap is insufficient for QA transition on a complex product. Industry standard is a 90-day parallel run. The internal team''s product context (knowing that the payment service has 3 edge cases during subscription changes) cannot be documented in a knowledge transfer doc — it comes from sustained product immersion. Never outsource QA without a 90-day parallel run.', '2026-05-24 11:00:00+00'),

(33, 'Marco Delgado', 'UK: 1,240 subscribers (target 1,000). CAC £31 (target ≤£35). LTV 6-month proxy £91 (target £85). CSAT 4.4/5. Clipper on-time 97%.', 5, 'Creator partnerships outperformed paid acquisition (CPA £19-£38 vs paid avg £38). UK market is highly creator-influenced in wellness. We should weight creator budget vs paid 60/40 for future EU market entries.', '2026-04-12 14:00:00+00'),

(34, 'Marco Delgado', 'Canada: 662 subscribers (target 500). CAC C$38 (target ≤C$45). Unit margin 38% after duty and shipping. Avg delivery 3.8-4.2 days.', 5, 'US-to-Canada is the lowest-friction international expansion model in subscription commerce. Ohio-to-Toronto ground shipping with DHL is effectively domestic in terms of transit time and process. This model is a template for future English-speaking market entry.', '2026-05-08 09:00:00+00'),

(35, 'Marco Delgado', 'Australia exit: 142 subscribers (target 300). Unit cost AUD$31 vs AUD$18 model. Business case negative. Market exit May 2.', 1, 'The fundamental error was using DHL published rates without factoring in Australian Customs inspection rates for cosmetics (industry-wide 40% inspection rate adds 3-7 day delay and AUD$8-13 per unit). Always get country-specific logistics quotes that include customs inspection probability and cost.', '2026-05-24 14:00:00+00'),

(36, 'Marco Delgado', 'B2B model superseded by DTC-first strategy for Germany. Two HR platform conversations paused. DTC Germany planned Q1 2027.', 3, 'The B2B-to-DTC LTV gap (3.2×) was the correct analysis, but we spent 2 months on B2B outreach before running this analysis. The DTC LTV comparison should have been the first analytical step, not the exit criterion.', '2026-06-14 10:00:00+00'),

(41, 'Aiko Yamamoto', 'Shipping cost $6.10/unit (target ≤$6.20). Avg delivery 3.1 days (was 5.2). Zero subscriber-facing disruption. Annualized saving: $364K.', 5, 'The 3-week parallel-fulfillment period was essential — it uncovered a zone mapping error for Alaska and Hawaii orders that would have been a significant disruption if caught post-cutover. Always run parallel fulfillment during 3PL migrations.', '2026-04-16 09:00:00+00'),

(43, 'Paulo Rivera', 'AWS bill: $59K/month (target ≤$62K). CDN p95 improvement: 34%. Zero data loss. GCP contract terminated May 15.', 5, 'Running 2-week parallel data replication before the BigQuery→Redshift cutover was the right call. The MD5 checksum audit found 3 records (out of 14M) that needed reconciliation — minor but would have been a data integrity issue without the audit. Always run parallel replication and audit before data store cutover.', '2026-05-12 10:00:00+00'),

(44, 'Paulo Rivera', 'Payment failure rate: 1.1% (vs 3.2% baseline). International failure: 1.8% (vs 7.1%). Involuntary churn from payment failure -41%. Dunning recovered $28K in first 30 days.', 5, 'Stripe''s smart retry logic works significantly better than we modeled because it uses network tokenization that updates expired cards automatically. The $28K dunning recovery was not in our ROI model at all — it is now a standard metric in our payment health dashboard.', '2026-04-27 14:00:00+00'),

(45, 'Aiko Yamamoto', 'Curation time: 5 hrs/week (target ≤8). Repeat-product rate: 1.4% (target ≤3%). Post-ship satisfaction: 4.4/5. 94% automation rate.', 5, 'The 6% exception rate (hypoallergenic, pregnancy, religious requirements) was higher than the ML team modeled because quiz data is incomplete for older subscribers who pre-date the detailed quiz. Retroactive profile completion campaign should be run to improve exception rate.', '2026-06-06 09:00:00+00'),

(46, 'Aiko Yamamoto', 'Pilot reversed June 2. Damage rate 7.8% (target ≤2.5%). COGS increase €0.41/box (vs €0.13 projected). NPS: flat. Pursuing alternative supplier.', 1, 'Novamont materials are proven for food and dry goods packaging but our Wellness boxes include glass containers. We did not specify glass-product compatibility in the RFP. Future packaging supplier evaluations must include a 30-day real-world stress test with our actual product mix before volume commitment.', '2026-06-22 10:00:00+00');

COMMIT;
